-- 会话摘要 RPC 增加「排除当前用户已隐藏的消息」。
--
-- 【为什么必须改】暗号链路里 B 端会隐藏自己回的位置、以及 A 发来的 where。
-- 若 RPC 不过滤，B 的会话列表会显示「[位置]」这条 B 自己看不到的消息，
-- 表现为「列表有摘要、点进去却没有这条消息」的诡异状态。
--
-- ⚠️ 必须 DROP 再 CREATE：PostgreSQL 不允许 CREATE OR REPLACE 改变已有函数的
--    返回行类型（SQLSTATE 42P13 cannot change return type of existing function）。
--    线上实际签名比 migrations 目录里的旧文件多三列（last_visible_content /
--    last_visible_content_type / last_visible_media_url），故这里按**线上真实定义**
--    重建，只新增 hidden 过滤，其余逻辑与列一字不动。
DROP FUNCTION IF EXISTS public.get_conversation_summaries();

CREATE FUNCTION public.get_conversation_summaries()
RETURNS TABLE (
  conversation_id UUID,
  visible_count BIGINT,
  unread_count BIGINT,
  last_visible_revoked BOOLEAN,
  last_visible_content TEXT,
  last_visible_content_type TEXT,
  last_visible_media_url TEXT
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
  WITH mine AS (
    SELECT d.message_id FROM message_deletes d WHERE d.user_id = auth.uid()
  ),
  hidden AS (
    SELECT v.message_id FROM message_visibility v WHERE v.user_id = auth.uid()
  ),
  ranked AS (
    SELECT m.conversation_id,
           m.id,
           m.read_at,
           m.sender_id,
           m.revoked_at,
           m.content,
           m.content_type,
           m.media_url,
           ROW_NUMBER() OVER (
             PARTITION BY m.conversation_id
             ORDER BY m.created_at DESC, m.id DESC
           ) AS rn
    FROM messages m
    WHERE NOT EXISTS (SELECT 1 FROM mine x WHERE x.message_id = m.id)
      AND NOT EXISTS (SELECT 1 FROM hidden h WHERE h.message_id = m.id)
      AND EXISTS (
        SELECT 1 FROM conversations c
        WHERE c.id = m.conversation_id
          AND (c.user1_id = auth.uid() OR c.user2_id = auth.uid())
      )
      AND NOT EXISTS (
        SELECT 1 FROM conversation_deletes cd
        WHERE cd.conversation_id = m.conversation_id AND cd.user_id = auth.uid()
      )
  )
  SELECT r.conversation_id,
         COUNT(*) AS visible_count,
         COUNT(*) FILTER (WHERE r.read_at IS NULL AND r.sender_id <> auth.uid()) AS unread_count,
         COALESCE(BOOL_OR(r.revoked_at IS NOT NULL) FILTER (WHERE r.rn = 1), FALSE) AS last_visible_revoked,
         MAX(r.content) FILTER (WHERE r.rn = 1) AS last_visible_content,
         MAX(r.content_type) FILTER (WHERE r.rn = 1) AS last_visible_content_type,
         MAX(r.media_url) FILTER (WHERE r.rn = 1) AS last_visible_media_url
  FROM ranked r
  GROUP BY r.conversation_id;
$$;
